scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var data = eval("scwin.data" + selectbox1.getValue());
    //xml 형식을 정의 하면 <w2:gridView 에 xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" 포함 합니다.
    dataList1.setData(data.slice(0));
}
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    console.log(data);
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        //debugger;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" ,") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" & ");
    console.log('label:' + label);
    return label;
};
scwin.grid1_onrowindexchange = function(row, oldRow) {
    console.log(row);
};
scwin.grid1_oncellindexchange = function(row, col, oldRow, oldCol) {};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.addEl = function(id, array) {
    var dataColId = WebSquare.util.getDataPrefix("col_id");
    var arr = jQuery("*["+dataColId+"='" + id + "']");
    for (var i = 0; i < arr.length; i++) {
        array.push(arr[i].innerText);
    }
    return array;
}
scwin.setVal1 = function() {
    scwin.addEl('col1', initArr);
}
scwin.setVal2 = function() {
    scwin.addEl('col1', beforeArr);
}
scwin.setVal3 = function() {
    scwin.addEl('col1', afterArr);
}
scwin.checkVal1 = function() {
    return initArr.length == beforeArr.length && initArr.every(function(v, i) {
        return v === beforeArr[i]
    });
}
scwin.checkVal2 = function() {
    return afterArr.length == beforeArr.length && afterArr.every(function(v, i) {
        return v === beforeArr[i]
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 gridView 분류1항목을 가,나,다로 필터링을 수행한다.
    //1. After executing the sample, filter the gridView Classification 1 items as follows.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_header2_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_header2_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_groupbyFilterBox_select_label').innerText == '(분류1 in [가 ,나 ,다])'", "true");

    //Test step 2. 이후에 분류1항목을 더블클릭하여 sorting한다.
    //2. Double-click classification 1 item to sort.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick('grid1_header2')");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    //Verify step 2. sorting이되어지고 sorting표시(삼각형)가 보여진다.
    //2. Sorting is done and sorting display (triangle) is shown.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "false");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_head_sort_asc').length == 1", "true");

    //Test step 3. '재조회'버튼을 클릭한다.
    //3. Click the 'Redial' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    //Verify step 3. sorting 및 sorting표시(삼각형)가 유지되어 보여진다.
    //3. The sorting and sorting marks (triangles) are kept and shown.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_head_sort_asc').length == 1", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
